// Fixed preview launcher that ignores any extra CLI arguments injected by
// external runners. The studio demo runner appends its own host/port flags
// after `npm run preview --`, which would otherwise override the values
// required by the task (0.0.0.0:3000 --strictPort). Spawning vite with an
// explicit argv sidesteps that override.
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "..");
const viteBin = resolve(repoRoot, "node_modules", "vite", "bin", "vite.js");

const child = spawn(
  process.execPath,
  [viteBin, "preview", "--host", "0.0.0.0", "--port", "3000", "--strictPort"],
  { stdio: "inherit", cwd: repoRoot, env: process.env },
);

const forward = (signal) => process.once(signal, () => child.kill(signal));
forward("SIGINT");
forward("SIGTERM");

child.on("exit", (code, signal) => {
  if (signal) process.kill(process.pid, signal);
  else process.exit(code ?? 0);
});

