    const delivery = await response.json();
    if (!response.ok) throw new Error(delivery.error || "启动失败");
    this.cacheDelivery(delivery);
    $("result-notice").textContent = "已启动原交付成果；没有重新运行 Agent，也没有改变原测试结论。";

